 59114                  if (JS_ToBigInt64(ctx, &v64, argv[3]))
 59115                      return JS_EXCEPTION;
 59116                  rep_val = v64;
 59117              }
 59118          } else {
 59119                  uint32_t v32;
 59120                  if (JS_ToUint32(ctx, &v32, argv[2]))
 59121                      return JS_EXCEPTION;
 59122                  v = v32;
 59123                  if (op == ATOMICS_OP_COMPARE_EXCHANGE) {
 59124                      if (JS_ToUint32(ctx, &v32, argv[3]))
 59125                          return JS_EXCEPTION;
 59126                      rep_val = v32;
 59127                  }
 59128          }
 59129          if (typed_array_is_oob(p))
